#include <iostream>
#include <cmath>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int a, b;
        cin >> a >> b;
        double delta = (b - a) / 500.0;
        double prob = 0.0;
        // x_i = a + i * delta, i = 0..499
        for (int i = 0; i < 500; ++i) {
            double x = a + i * delta;
            prob += sin(sqrt(x)) / 5.68 * delta;
        }
        cout << (prob > 0.5 ? 1 : 0) << '\n';
    }
    return 0;
}
